// Parent portal (custdash) + operator Customers/families leftovers, parent sign-in page.
import { fromRows } from "./_rows";

type Form = { o?: string; t?: string; f?: string; m?: string; x: string };
/** Plural rows: one column per locale; each entry is either a single string (all forms) or {o: one, t: two, f: few, m: many, x: other}. */
function plur(base: string, cols: (string | Form)[]): Record<string, string[]> {
  const out: Record<string, string[]> = {};
  const forms: [string, keyof Form][] = [["one", "o"], ["two", "t"], ["few", "f"], ["many", "m"], ["other", "x"]];
  for (const [name, k] of forms) {
    out[`${base}_${name}`] = cols.map((c) => {
      if (typeof c === "string") return c;
      return (c[k] ?? c.x) as string;
    });
  }
  return out;
}

